{
  "command": "S=/tmp/claude-1000/-mnt-c-Users-cabot-OneDrive-Documents-Research-Cambridge-X3I/c4794a53-4881-4aa9-8b9b-7c033457fa8b/scratchpad; sed -n 538,600p $S/txt/reiss2019.txt; sed -n 636,655p $S/txt/reiss2019.txt",
  "description": "Read Reiss 2019 Table 1"
}

{
  "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6900206",
  "prompt": "Extract all quantitative validation metrics verbatim with table numbers: ME, MAE, RMSE, correlation coefficient, skill score of solar wind speed (and density, B, temperature if given) for EUHFORIA vs ACE for 2008 and 2012, and comparisons with persistence; event-based HSS metrics (hits, misses, false alarms, POD, FAR, TS, bias, timing errors in hours); any statement on density or magnetic field under/overprediction and slow/fast wind speed underestimation."
}

{
  "url": "https://arxiv.org/pdf/1907.07461v2",
  "prompt": "Give the RMSE values and hit/miss/false-alarm counts."
}

{
  "command": "S=/tmp/claude-1000/-mnt-c-Users-cabot-OneDrive-Documents-Research-Cambridge-X3I/c4794a53-4881-4aa9-8b9b-7c033457fa8b/scratchpad; mkdir -p $S/dl && cd $S/dl && curl -sL -A \"Mozilla/5.0\" -o hint2019.pdf https://arxiv.org/pdf/1907.07461v2; ls -la; file hint2019.pdf",
  "description": "Download Hinterreiter 2019 arXiv PDF"
}

{
  "command": "S=/tmp/claude-1000/-mnt-c-Users-cabot-OneDrive-Documents-Research-Cambridge-X3I/c4794a53-4881-4aa9-8b9b-7c033457fa8b/scratchpad; mkdir -p $S/lit_dl; mv $S/dl/hint2019.pdf $S/lit_dl/; cd /tmp && python3 -I $S/scripts/p2t.py $S/lit_dl/hint2019.pdf $S/txt/hint2019.txt; grep -n -i -E \"RMSE|hits|false alarm|misses|underestimat|overestimat|km s|km/s\" $S/txt/hint2019.txt | head -60",
  "description": "Extract Hinterreiter 2019 text and search metrics"
}

{
  "command": "S=/tmp/claude-1000/-mnt-c-Users-cabot-OneDrive-Documents-Research-Cambridge-X3I/c4794a53-4881-4aa9-8b9b-7c033457fa8b/scratchpad; sed -n 128,140p $S/txt/hint2019.txt; grep -n -i -B2 -A3 \"density\" $S/txt/hint2019.txt | head -50; sed -n 355,372p $S/txt/hint2019.txt",
  "description": "Read Hinterreiter density and timing statements"
}

{
  "query": "Owens Spence McGregor 2008 \"Metrics for solar wind prediction models\" WSA ENLIL 8 years L1 observations pdf",
  "mode": "standard"
}

{
  "query": "Reiss 2016 Space Weather \"Verification of high-speed solar wind stream forecasts using operational solar wind models\" RMSE",
  "mode": "standard"
}

{
  "query": "Reiss 2023 Space Weather \"Unifying the validation of ambient solar wind models\" open access",
  "mode": "standard"
}

{
  "query": "Lang Owens 2019 Space Weather \"A Variational Approach to Data Assimilation in the Solar Wind\" BRaVDA RMSE",
  "mode": "standard"
}

{
  "query": "Lang Witherington Turner Owens 2021 \"Improving solar wind forecasting using data assimilation\" Space Weather RMSE reduction",
  "mode": "standard"
}

{
  "query": "Owens 2020 Solar Physics \"A Computationally Efficient, Time-Dependent Model of the Solar Wind for Use as a Surrogate to Three-Dimensional Numerical Magnetohydrodynamic Simulations\" HUXt",
  "mode": "standard"
}

{
  "command": "S=/tmp/claude-1000/-mnt-c-Users-cabot-OneDrive-Documents-Research-Cambridge-X3I/c4794a53-4881-4aa9-8b9b-7c033457fa8b/scratchpad; grep -n -i -E \"km s|km/s|RMSE|MSE|correlation|hits|false|Table|timing|underestimat|overestimat|nT|density\" $S/txt/owens2008.txt | head -100",
  "description": "Search Owens 2008 text for metrics"
}

{
  "command": "S=/tmp/claude-1000/-mnt-c-Users-cabot-OneDrive-Documents-Research-Cambridge-X3I/c4794a53-4881-4aa9-8b9b-7c033457fa8b/scratchpad; sed -n 395,700p $S/txt/owens2008.txt",
